mapper.select:
SELECT v.id AS versionId,v.version_no AS versionNo,v.source_type AS sourceType,v.created_at AS createdAt,v.created_by AS createdBy,
       d.factory_code AS factoryCode,d.material_id AS materialId,d.material_name AS materialName,d.plan_month AS planMonth,d.forecast_qty AS forecastQty
FROM forecast_detail d JOIN forecast_version v ON v.id=d.version_id
WHERE d.factory_code=#{factoryCode} AND d.material_id=#{materialId}
ORDER BY v.version_no DESC,d.plan_month LIMIT #{limit} OFFSET #{offset}
